css:
/* 全段を斜め＋向きを交互に反転 */
.band:nth-child(odd) {clip-path:polygon(0 0,100% 0,100% 82%,0 100%)}
.band:nth-child(even){clip-path:polygon(0 12%,100% 0,100% 100%,0 88%)}
.band{margin-top:-5%}            /* 斜辺で欠ける分を詰めて隙間を消す */

/* 一辺だけ斜め: 前セクションの底を三角で落とす */
.wedge{position:absolute; inset:0 auto auto 0; width:100%; height:160px;
  background:#f2f1e6; clip-path:polygon(0 0,44% 0,0 100%)}

/* 右下から差し込む色面 */
.sec{position:relative; overflow:hidden}
.sec::after{content:''; position:absolute; right:0; bottom:0;
  width:60%; height:120px; background:#f2f2e4;
  clip-path:polygon(100% 0,100% 100%,0 100%); z-index:-1}
